package com.ragpipeline.service;
import com.ragpipeline.kafka.IngestionProducer;import com.ragpipeline.model.*;import com.ragpipeline.repository.*;import lombok.RequiredArgsConstructor;import org.apache.tika.Tika;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@Service @RequiredArgsConstructor public class DocumentIngestionService {private final DocumentRepository docs;private final ChunkRepository chunks;private final IngestionProducer producer;private final Tika tika=new Tika();
 public Document ingest(MultipartFile f,String strategy,String organization,String authority,String documentType,Boolean current){try{String name=Objects.requireNonNullElse(f.getOriginalFilename(),"upload");String content=tika.parseToString(f.getInputStream());Metadata metadata=metadata(name,content,organization,authority,documentType,current);Document d=Document.builder().fileName(name).fileType(Objects.requireNonNullElse(f.getContentType(),"application/octet-stream")).rawContent(content).sourcePath(null).chunkingStrategy(strategy==null?"RECURSIVE":strategy).organization(metadata.organization()).authority(metadata.authority()).documentType(metadata.documentType()).current(metadata.current()).build();d=docs.save(d);producer.send(IngestionJob.builder().documentId(d.getId()).fileName(d.getFileName()).chunkingStrategy(d.getChunkingStrategy()).build());return d;}catch(Exception e){throw new IllegalArgumentException("Unable to parse or enqueue uploaded document",e);}}
 private Metadata metadata(String name,String content,String organization,String authority,String documentType,Boolean current){String lower=(name+" "+content).toLowerCase(Locale.ROOT);String org=organization!=null?organization:(lower.contains("acme cloud")?"Acme":lower.contains("techcorp")?"TechCorp":"Unknown");String inferredAuthority=lower.contains("superseded")||lower.contains("historical")||lower.contains("archived")?"HISTORICAL":!"TechCorp".equalsIgnoreCase(org)&&!"Unknown".equalsIgnoreCase(org)?"EXTERNAL":lower.contains("faq")||lower.contains("training")?"REFERENCE":"AUTHORITATIVE";String type=documentType!=null?documentType:(lower.contains("faq")?"FAQ":lower.contains("announcement")?"ANNOUNCEMENT":lower.contains("training")?"TRAINING":"POLICY");String level=authority!=null?authority:inferredAuthority;return new Metadata(org,level.toUpperCase(Locale.ROOT),type.toUpperCase(Locale.ROOT),current!=null?current:"AUTHORITATIVE".equalsIgnoreCase(level));}
 private record Metadata(String organization,String authority,String documentType,Boolean current){} public void markIndexed(UUID id){docs.findById(id).ifPresent(d->{d.setStatus("INDEXED");docs.save(d);});}}
